def rgb(value):
    """A #RRGGBB colour as (red, green, blue), 0 to 255."""
    value = value.lstrip("#")
    return tuple(int(value[i:i + 2], 16) for i in (0, 2, 4))


def mix(top, amount, under):
    """``top`` at ``amount`` (0 to 1) over ``under``, as #RRGGBB: a wash for a surface that draws opaque."""
    a, b = rgb(top), rgb(under)
    return "#" + "".join(f"{round(x * amount + y * (1 - amount)):02X}" for x, y in zip(a, b))
